// Single import point for the measured numbers. They are generated by story/scripts/build_data.py from
// experiments/results/results.md and the planner itself. No number on the page is typed by hand.
import raw from './evidence.json'

export const R = raw.results
export const P = raw.perception
export const F = raw.facts
export const COUNTS = raw.counts
export const TRIAGE = raw.triage
export const PLANS = raw.plans

export const pct = (x) => `${Math.round(x * 100)}%`
export const pct1 = (x) => `${(x * 100).toFixed(1)}%`
export const secs = (x) => `${x} s`

export const ORDER = raw.order
export const STEPS = raw.steps
